// Minimum number of cart lines for the bulk discount, and its rate.
export const BULK_MIN_LINES = 2;
export const BULK_RATE = 0.05;

// Cart total in cents. `discount` is the customer's discount rate (0.1 = 10%).
// The customer's discount is applied once; carts with `bulkMinLines` or more
// lines (2 by default) then get an extra 5% bulk discount, also applied once.
export function total(items, discount = 0, { bulkMinLines = BULK_MIN_LINES } = {}) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= bulkMinLines ? BULK_RATE : 0;
  return Math.round(subtotal * (1 - discount) * (1 - bulk));
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}
EOF
cat > src/invoice.js <<'EOF'
import { total } from './cart.js';

// The printed wholesale price list gives 5% off from 10 lines. It is not tied to
// the cart's bulk-discount threshold, which has since been lowered.
export const WHOLESALE_BULK_MIN_LINES = 10;

// Invoices for wholesale orders (#7). The amount due follows the printed price
// list wholesale customers order from — list price below 10 lines, 5% off from
// 10 lines, half a yen rounded up.
export function invoice(customer, items) {
  return { customer, due: total(items, 0, { bulkMinLines: WHOLESALE_BULK_MIN_LINES }) };
}
EOF
cat > tests/cart.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

test('total without discount', () => {
  assert.equal(total([{ price: 250, qty: 1 }]), 250);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});

test('bulk discount rounds the half yen up', () => {
  assert.equal(total(lines(10, 11)), 105); // 110 * 0.95 = 104.5
});

test('customer discount is applied once (#12)', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

test('bulk discount is applied once, after the customer discount (#12)', () => {
  assert.equal(total(lines(10, 1000), 0.1), 8550); // 10000 * 0.9 * 0.95
});

test('bulk discount starts at 2 lines', () => {
  assert.equal(total(lines(1, 1000)), 1000);
  assert.equal(total(lines(2, 1000)), 1900);
  assert.equal(total(lines(2, 500), 0.1), 855); // 1000 * 0.9 * 0.95
});

test('a single line with a large quantity is not a bulk cart', () => {
  assert.equal(total([{ price: 100, qty: 20 }]), 2000);
});
EOF
