  // invoices: must be identical to before for every length
  if (invoice('x', items).due !== oldTotal(items)) bad++;
  // cart at rate 0: identical outside the 2..9-line range that the threshold change targets
  if ((len < 2 || len >= 10) && total(items, 0) !== oldTotal(items, 0)) bad++;
  n++;
}
console.log({ n, bad });
